CREATE TRIGGER invalidate_naru_correction_word AFTER UPDATE OF word,definition,book_id,word_number,part_of_speech,source_sheet,source_entry_id,example_sentence,example_meaning ON words WHEN OLD.word IS NOT NEW.word OR OLD.definition IS NOT NEW.definition OR OLD.book_id IS NOT NEW.book_id OR OLD.word_number IS NOT NEW.word_number OR OLD.part_of_speech IS NOT NEW.part_of_speech OR OLD.source_sheet IS NOT NEW.source_sheet OR OLD.source_entry_id IS NOT NEW.source_entry_id OR OLD.example_sentence IS NOT NEW.example_sentence OR OLD.example_meaning IS NOT NEW.example_meaning BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_word',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (c.word_id=NEW.id); END;
CREATE TRIGGER invalidate_naru_correction_entry_update AFTER UPDATE ON catalog_source_entries  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_entry_update',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.id IN(c.original_source_entry_id,c.corrected_source_entry_id)); END;
CREATE TRIGGER invalidate_naru_correction_source_update AFTER UPDATE ON catalog_workbook_sources  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_source_update',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.id IN(json_extract(c.proof_json,'$.originalSourceId'),json_extract(c.proof_json,'$.correctedSourceId'))); END;
CREATE TRIGGER invalidate_naru_correction_archive_update AFTER UPDATE ON catalog_workbook_sheet_rows  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_archive_update',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.source_id IN(json_extract(c.proof_json,'$.originalSourceId'),json_extract(c.proof_json,'$.correctedSourceId'))); END;
CREATE TRIGGER invalidate_naru_correction_link_update AFTER UPDATE ON catalog_word_source_links  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_link_update',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.word_id=c.word_id); END;
CREATE TRIGGER invalidate_naru_correction_entry_delete BEFORE DELETE ON catalog_source_entries  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_entry_delete',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.id IN(c.original_source_entry_id,c.corrected_source_entry_id)); END;
CREATE TRIGGER invalidate_naru_correction_source_delete BEFORE DELETE ON catalog_workbook_sources  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_source_delete',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.id IN(json_extract(c.proof_json,'$.originalSourceId'),json_extract(c.proof_json,'$.correctedSourceId'))); END;
CREATE TRIGGER invalidate_naru_correction_archive_delete BEFORE DELETE ON catalog_workbook_sheet_rows  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_archive_delete',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.source_id IN(json_extract(c.proof_json,'$.originalSourceId'),json_extract(c.proof_json,'$.correctedSourceId'))); END;
CREATE TRIGGER invalidate_naru_correction_link_delete BEFORE DELETE ON catalog_word_source_links  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_link_delete',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.word_id=c.word_id); END;
CREATE TRIGGER invalidate_naru_correction_entry_insert AFTER INSERT ON catalog_source_entries  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_entry_insert',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (NEW.source_id IN(json_extract(c.proof_json,'$.originalSourceId'),json_extract(c.proof_json,'$.correctedSourceId'))); END;
CREATE TRIGGER invalidate_naru_correction_archive_insert AFTER INSERT ON catalog_workbook_sheet_rows  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_archive_insert',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (NEW.source_id IN(json_extract(c.proof_json,'$.originalSourceId'),json_extract(c.proof_json,'$.correctedSourceId'))); END;
CREATE TRIGGER invalidate_naru_correction_ledger AFTER UPDATE OF word_id,original_source_entry_id,corrected_source_entry_id,proof_json ON catalog_word_source_corrections WHEN OLD.word_id IS NOT NEW.word_id OR OLD.original_source_entry_id IS NOT NEW.original_source_entry_id OR OLD.corrected_source_entry_id IS NOT NEW.corrected_source_entry_id OR OLD.proof_json IS NOT NEW.proof_json BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_ledger',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (c.id=OLD.id); END;
CREATE TRIGGER invalidate_naru_correction_approval AFTER UPDATE OF edition,rights_status,review_status,book_id ON material_source_ledger WHEN OLD.edition IS NOT NEW.edition OR OLD.rights_status IS NOT NEW.rights_status OR OLD.review_status IS NOT NEW.review_status OR OLD.book_id IS NOT NEW.book_id BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_approval',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (json_extract(c.proof_json,'$.bookId')=OLD.book_id); END;
CREATE TRIGGER invalidate_naru_correction_link_insert AFTER INSERT ON catalog_word_source_links  BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_link_insert',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (NEW.word_id=c.word_id); END;
CREATE TRIGGER clear_naru_correction_flags AFTER INSERT ON catalog_word_source_correction_invalidations BEGIN UPDATE words SET aichi_exam_appeared=0,example_meaning_supplemented=0 WHERE id=(SELECT word_id FROM catalog_word_source_corrections WHERE id=NEW.correction_id); END;
CREATE TRIGGER preserve_naru_correction_history BEFORE DELETE ON catalog_word_source_corrections BEGIN SELECT RAISE(ABORT,'Correction history is immutable'); END;
CREATE TRIGGER refuse_invalidated_naru_correction_flags AFTER UPDATE OF aichi_exam_appeared,example_meaning_supplemented ON words WHEN (NEW.aichi_exam_appeared<>0 OR NEW.example_meaning_supplemented<>0) AND EXISTS(SELECT 1 FROM catalog_word_source_corrections c JOIN catalog_word_source_correction_invalidations i ON i.correction_id=c.id WHERE c.word_id=NEW.id) BEGIN UPDATE words SET aichi_exam_appeared=0,example_meaning_supplemented=0 WHERE id=NEW.id; END;
